from collections import Counter, deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            if maxr - minr < 2 or maxc - minc < 2:
                continue
            perimeter = {(y, x) for y in range(minr, maxr + 1)
                         for x in range(minc, maxc + 1)
                         if y in (minr, maxr) or x in (minc, maxc)}
            if set(cells) != perimeter:
                continue
            cavity_h = maxr - minr - 1
            cavity_w = maxc - minc - 1
            fill = 7 if cavity_h % 2 and cavity_w % 2 else 2
            for y in range(minr + 1, maxr):
                for x in range(minc + 1, maxc):
                    if grid[y][x] == background:
                        out[y][x] = fill
    return out


